{"path":"src/components/ErrorBoundary.tsx","content":"import React, { Component, ErrorInfo, ReactNode } from "react";

interface Props {
  children: ReactNode;
  fallback?: (error: Error, retry: () => void) => ReactNode;
  onError?: (error: Error, errorInfo: ErrorInfo) => void;
}

interface State {
  error: Error | null;
  errorInfo: ErrorInfo | null;
}

export class ErrorBoundary extends Component<Props, State> {
  state: State = { error: null, errorInfo: null };

  static getDerivedStateFromError(error: Error): Partial<State> {
    return { error };
  }

  componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    this.setState({ errorInfo });

    console.error("[ErrorBoundary] Caught render error:", error);
    console.error("[ErrorBoundary] Component stack:", errorInfo.componentStack);

    this.props.onError?.(error, errorInfo);
  }

  retry = () => {
    this.setState({ error: null, errorInfo: null });
  };

  render() {
    const { error, errorInfo } = this.state;
    const { children, fallback } = this.props;

    if (!error) return children;

    if (fallback) return fallback(error, this.retry);

    return (
      <DefaultFallback
        error={error}
        errorInfo={errorInfo}
        onRetry={this.retry}
      />
    );
  }
}

function DefaultFallback({
  error,
  errorInfo,
  onRetry,
}: {
  error: Error;
  errorInfo: ErrorInfo | null;
  onRetry: () => void;
}) {
  return (
    <div
      role="alert"
      style={{
        padding: "24px",
        border: "1px solid #f87171",
        borderRadius: "8px",
        background: "#fef2f2",
        color: "#991b1b",
        fontFamily: "sans-serif",
        maxWidth: "640px",
        margin: "24px auto",
      }}
    >
      <h2 style={{ margin: "0 0 8px", fontSize: "1.125rem" }}>
        Something went wrong
      </h2>
      <p style={{ margin: "0 0 8px", fontSize: "0.875rem" }}>
        {error.message}
      </p>
      {process.env.NODE_ENV !== "production" && errorInfo && (
        <details style={{ marginBottom: "16px" }}>
          <summary
            style={{ cursor: "pointer", fontSize: "0.75rem", opacity: 0.7 }}
          >
            Stack trace
          </summary>
          <pre
            style={{
              marginTop: "8px",
              fontSize: "0.7rem",
              overflowX: "auto",
              whiteSpace: "pre-wrap",
              wordBreak: "break-word",
            }}
          >
            {error.stack}
            {errorInfo.componentStack}
          </pre>
        </details>
      )}
      <button
        onClick={onRetry}
        style={{
          padding: "8px 16px",
          background: "#dc2626",
          color: "#fff",
          border: "none",
          borderRadius: "4px",
          cursor: "pointer",
          fontSize: "0.875rem",
        }}
      >
        Retry
      </button>
    </div>
  );
}
"}

