{"path":"src/components/ErrorBoundary.test.tsx","content":"import React, { useState } from "react";
import { render, screen, fireEvent } from "@testing-library/react";
import { ErrorBoundary } from "./ErrorBoundary";

const Bomb = ({ shouldThrow }: { shouldThrow: boolean }) => {
  if (shouldThrow) throw new Error("Test explosion");
  return <div>Safe content</div>;
};

const ToggleBomb = () => {
  const [boom, setBoom] = useState(false);
  return (
    <>
      <button onClick={() => setBoom(true)}>Trigger error</button>
      <ErrorBoundary>
        <Bomb shouldThrow={boom} />
      </ErrorBoundary>
    </>
  );
};

beforeEach(() => {
  jest.spyOn(console, "error").mockImplementation(() => {});
});

afterEach(() => {
  jest.restoreAllMocks();
});

test("renders children when no error", () => {
  render(
    <ErrorBoundary>
      <Bomb shouldThrow={false} />
    </ErrorBoundary>
  );
  expect(screen.getByText("Safe content")).toBeInTheDocument();
});

test("shows default fallback on error", () => {
  render(
    <ErrorBoundary>
      <Bomb shouldThrow />
    </ErrorBoundary>
  );
  expect(screen.getByRole("alert")).toBeInTheDocument();
  expect(screen.getByText(/something went wrong/i)).toBeInTheDocument();
  expect(screen.getByText("Test explosion")).toBeInTheDocument();
});

test("retry clears error state", () => {
  render(<ToggleBomb />);
  fireEvent.click(screen.getByText("Trigger error"));
  expect(screen.getByRole("alert")).toBeInTheDocument();
  fireEvent.click(screen.getByText("Retry"));
  expect(screen.getByText("Safe content")).toBeInTheDocument();
});

test("calls onError prop with error details", () => {
  const onError = jest.fn();
  render(
    <ErrorBoundary onError={onError}>
      <Bomb shouldThrow />
    </ErrorBoundary>
  );
  expect(onError).toHaveBeenCalledWith(
    expect.any(Error),
    expect.objectContaining({ componentStack: expect.any(String) })
  );
});

test("renders custom fallback when provided", () => {
  render(
    <ErrorBoundary
      fallback={(err, retry) => (
        <div>
          <span>Custom: {err.message}</span>
          <button onClick={retry}>Try again</button>
        </div>
      )}
    >
      <Bomb shouldThrow />
    </ErrorBoundary>
  );
  expect(screen.getByText("Custom: Test explosion")).toBeInTheDocument();
  expect(screen.getByText("Try again")).toBeInTheDocument();
});
"}

